    /// <see cref="AppliedPostRereadFailed"/> the names are the ones of the outcomes of the classification by frontier.
    /// </summary>
    public enum EditUpdateStatus
    {
        /// <summary>Nothing was done. It is also the default value.</summary>
        Unavailable,

